/* From Uiverse.io by AqFox - Tags: button */
.__UIV_SCOPE__ .btn {
  position: relative;
  display: inline-block;
  width: auto;
  height: auto;
  background-color: transparent;
  border: none;
  cursor: pointer;
  margin: 0px 25px 15px;
  min-width: 150px;
}

.__UIV_SCOPE__ .btn span {
  position: relative;
  display: inline-block;
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 2px;
  text-transform: uppercase;
  top: 0;
  left: 0;
  width: 100%;
  padding: 15px 20px;
  transition: 0.3s;
}

.__UIV_SCOPE__ .btn-1::before {
  background-color: #004dff;
  transition: 0.3s ease-out;
}

.__UIV_SCOPE__ .btn-1 span {
  color: rgb(255,255,255);
  border: 1px solid #004dff;
  transition: 0.2s 0.1s;
}

.__UIV_SCOPE__ .btn-1 span:hover {
  color: #004dff;
  transition: 0.2s 0.1s;
}

.__UIV_SCOPE__ :active, .__UIV_SCOPE__ :hover, .__UIV_SCOPE__ :focus {
  outline: 0!important;
  outline-offset: 0;
}

.__UIV_SCOPE__ ::before,
.__UIV_SCOPE__ ::after {
  position: absolute;
  content: "";
}

.__UIV_SCOPE__ .btn.hover-filled-slide-left::before {
  top: 0;
  bottom: 0;
  left: 0;
  height: 100%;
  width: 100%;
}

.__UIV_SCOPE__ .btn.hover-filled-slide-left:hover::before {
  width: 0%;
}
